"""Embeds web/altherma.html, gzipped, into components/daikin_x10a/diagram_html.h.

Run after changing the page:  python3 tools/embed_diagram.py
The page is derived from the ESPAltherma web interface (MIT License, Copyright (c) 2020 Raomin).
"""

import gzip
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
html = (ROOT / "web" / "altherma.html").read_bytes()
data = gzip.compress(html, compresslevel=9, mtime=0)
lines = [
    "#pragma once",
    "// Generated by tools/embed_diagram.py from web/altherma.html - do not edit.",
    "#include <cstdint>",
    "",
    "namespace esphome {",
    "namespace daikin_x10a {",
    "",
    f"// {len(html)} bytes, gzipped",
    "static const uint8_t DIAGRAM_HTML_GZ[] = {",
]
for i in range(0, len(data), 20):
    lines.append("    " + ", ".join(f"0x{b:02x}" for b in data[i:i + 20]) + ",")
lines += ["};", "", "}  // namespace daikin_x10a", "}  // namespace esphome", ""]
(ROOT / "components" / "daikin_x10a" / "diagram_html.h").write_text("\n".join(lines))
print(f"diagram_html.h: {len(html)} -> {len(data)} bytes")
